	switch discriminator {
	case "cloud_drive":
		return t.AsCloudDriveACLInput()
	case "nfsv4":
		return t.AsNfsV4ACLInput()
	case "nt":
		return t.AsNtACLInput()
	case "posix":
		return t.AsPosixACLInput()
	case "s3":
		return t.AsS3ACLInput()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
